import {state,update,serverBacked,textContent} from './store.js';
import {formatAiMarkdown} from './ai-format.js';
import {findRelevantArticles} from './ai-search.js';
import {draftFromConversation} from './ai-article-history.js';

const uid=()=>crypto.randomUUID();
const chatById=id=>(state.aiChats||[]).find(chat=>chat.id===id);
const selected=()=>chatById(state.activeAiChatId)||(state.aiChats||[])[0];
const safeWebURL=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return'';}};
const webStatusText=status=>({disabled:'Поиск в интернете не настроен. Ответ основан на общих знаниях модели.',failed:'Поиск в интернете недоступен. Ответ основан на общих знаниях модели.',empty:'Поиск в интернете не нашёл подходящих материалов. Ответ основан на общих знаниях модели.'}[status]||'');
function renderExternalSources(message,ui){const sources=Array.isArray(message.webSources)?message.webSources.filter(s=>safeWebURL(s.url)):[];return sources.length?`<div class="ai-sources"><strong>Найдено в интернете</strong>${sources.map(s=>`<a href="${ui.esc(safeWebURL(s.url))}" target="_blank" rel="noopener noreferrer">${ui.esc(s.title)} ${ui.icon('external')}</a>`).join('')}</div>`:'';}
let working=false;

function textToDraft(text,escape){
  const lines=String(text).replace(/\r/g,'').trim().split('\n');
  const title=(lines.shift()||'Черновик инструкции').replace(/^\s*(?:#{1,6}\s*|(?:заголовок|название)\s*:\s*)/i,'').trim().slice(0,180)||'Черновик инструкции';
  const inline=value=>escape(value).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');let list='',parts=[];
  for(const line of lines){const value=line.trim(),heading=value.match(/^#{1,4}\s+(.+)$/),item=value.match(/^(?:[-*]\s+|\d+[.)]\s+)(.+)$/);if(item){if(!list){list=/^\d/.test(value)?'ol':'ul';parts.push('<'+list+'>');}parts.push('<li><p>'+inline(item[1])+'</p></li>');continue;}if(list){parts.push('</'+list+'>');list='';}if(heading)parts.push('<h2>'+inline(heading[1])+'</h2>');else if(value)parts.push('<p>'+inline(value)+'</p>');}if(list)parts.push('</'+list+'>');const body=parts.join('')||'<p>Проверьте и дополните инструкцию.</p>';
  return {title,summary:'',body,category:'workplace',department:'Все отделы',effective:new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'}),tags:[],note:'Черновик подготовлен ИИ'};
}
function contextFor(messages,articles){const question=[...messages].reverse().find(m=>m.role==='user')?.content||'',matches=findRelevantArticles(question,articles,textContent);return{text:matches.map(a=>`Статья: ${a.title}\n${a.summary}\n${textContent(a.body).slice(0,1800)}`).join('\n\n'),sources:matches.map(a=>({id:a.id,title:a.title}))};}
async function requestAI(messages,task='chat'){
  const context=task==='chat'?contextFor(messages,state.articles):{text:'',sources:[]};const response=await fetch('/api/assistant/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:messages.map(({role,content})=>({role,content})),context:context.text,task,webSearch:task==='chat'&&!context.sources.length})});
  const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||'Не удалось обратиться к ИИ.');if(typeof payload.text!=='string'||!payload.text.trim())throw new Error('Провайдер вернул пустой ответ.');return{text:payload.text.trim(),sources:context.sources,webSources:Array.isArray(payload.webSources)?payload.webSources:[],webStatus:payload.webStatus};
}

export function previewGeneratedArticle(text,ui,onAccept){
  ui.showModal('Черновик, подготовленный ИИ',`<p>Проверьте факты и шаги. Статья не будет опубликована автоматически.</p><pre class="ai-draft-preview">${ui.esc(text)}</pre><div class="modal-footer"><button class="btn" data-action="close-modal">Отмена</button><button class="btn btn-primary" id="ai-draft-accept">Перенести в редактор</button></div>`,true);
  document.querySelector('#ai-draft-accept')?.addEventListener('click',()=>{const draft=textToDraft(text,ui.esc);onAccept(draft);});
}
export function requestEditorDraft(ui,accept){
  ui.showModal('Помочь оформить статью',`<p>Опишите проблему, диагностику и проверенное решение. Не добавляйте пароли и секреты: текст отправится ИИ-провайдеру.</p><form id="ai-draft-form"><div class="field"><label for="ai-draft-notes">Заметки для инструкции</label><textarea id="ai-draft-notes" rows="7" maxlength="6000" required placeholder="Что произошло, что проверили и как решили проблему"></textarea></div><p class="tiny muted">После генерации можно проверить черновик. Перенос заменит текст текущего редактора только после подтверждения.</p><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Отмена</button><button class="btn btn-primary" type="submit">Подготовить черновик</button></div></form>`,true);
  document.querySelector('#ai-draft-form')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,notes=form.querySelector('#ai-draft-notes').value.trim(),button=form.querySelector('[type=submit]');if(!notes)return;button.disabled=true;button.textContent='Готовим черновик…';try{const {text}=await requestAI([{role:'user',content:notes}],'article');if(!form.isConnected)return;previewGeneratedArticle(text,ui,draft=>{ui.closeModal();accept(draft);});}catch(error){if(!form.isConnected)return;ui.toast(error.message);button.disabled=false;button.textContent='Подготовить черновик';}});
}

export function mountAssistant(ui){
 const root=document.querySelector('#main-content');let failure='';
 function render(){if(!root.isConnected||!root.querySelector('#ai-chat-root'))return;const chat=selected(),chats=state.aiChats||[],messages=chat?.messages||[];root.querySelector('#ai-chat-root').innerHTML=`<div class="ai-chat-layout"><aside class="ai-chat-sidebar"><div class="between"><strong>Диалоги</strong><button class="btn btn-small" data-chat-action="new" ${working?'disabled':''}>${ui.icon('plus')}Новый</button></div><div class="ai-chat-list">${chats.length?chats.map(c=>`<button class="ai-chat-item ${c.id===chat?.id?'active':''}" data-chat-action="select" data-chat-id="${ui.esc(c.id)}" ${working?'disabled':''}>${ui.esc(c.title||'Новый диалог')}</button>`).join(''):'<p class="tiny muted">Пока нет диалогов</p>'}</div><p class="tiny muted">${serverBacked?'Диалоги общие для всех, кто имеет доступ к этому рабочему пространству.':'Диалоги хранятся только в этом браузере.'}</p></aside><section class="ai-conversation"><div class="ai-chat-heading"><div><h2>${ui.esc(chat?.title||'Новый диалог')}</h2><p class="tiny muted">Учитываются последние сообщения; история не является личной.</p></div><div class="ai-chat-actions"><button class="btn btn-small" data-chat-action="article" ${!messages.length||working?'disabled':''}>${ui.icon('file')}Подготовить статью</button><button class="btn btn-small" data-chat-action="clear" ${!messages.length||working?'disabled':''}>Очистить</button><button class="icon-btn" data-chat-action="delete" aria-label="Удалить диалог" ${!chat||working?'disabled':''}>${ui.icon('trash')}</button></div></div><div class="ai-messages" aria-live="polite">${messages.length?messages.map(m=>`<article class="ai-chat-message ${m.role==='user'?'is-user':'is-assistant'}"><div class="between"><strong>${m.role==='user'?'Вы':'ИИ-помощник'}</strong><button class="icon-btn" data-chat-action="delete-message" data-message-id="${ui.esc(m.id)}" aria-label="Удалить сообщение" ${working?'disabled':''}>${ui.icon('trash')}</button></div><div class="ai-message-text">${m.role==='assistant'?formatAiMarkdown(m.content):ui.esc(m.content)}</div>${m.sources?.length?`<div class="ai-sources"><strong>Переданные материалы</strong>${m.sources.map(s=>`<a href="#/article/${encodeURIComponent(s.id)}">${ui.esc(s.title)} ${ui.icon('arrow')}</a>`).join('')}</div>`:''}${renderExternalSources(m,ui)}${webStatusText(m.webStatus)?`<p class="ai-web-status">${ui.esc(webStatusText(m.webStatus))}</p>`:''}</article>`).join(''):`<div class="ai-chat-welcome"><span class="ai-symbol">${ui.icon('sparkles')}</span><h2>Разберёмся вместе.</h2><p>Опишите проблему — помощник поможет её исследовать, даже если готовой статьи нет.</p></div>`}${working?'<p class="ai-loading">Готовлю ответ…</p>':''}${failure?`<div class="ai-chat-error" role="alert"><p>${ui.esc(failure)}</p>${messages.at(-1)?.role==='user'?'<button class="btn btn-small" data-chat-action="retry">Повторить запрос</button>':''}</div>`:''}</div><form id="ai-form" class="ai-composer"><textarea id="ai-query" rows="1" maxlength="6000" placeholder="Опишите проблему или задайте вопрос…" title="Enter — отправить, Shift+Enter — новая строка" aria-label="Ваш вопрос" ${working?'disabled':''} required></textarea><div class="ai-composer-bottom"><span>${ui.icon('shield')}История и статьи передаются ИИ; если статья не найдена, вопрос может быть отправлен в поиск. Не вводите секреты.</span><button class="btn btn-primary" type="submit" ${working?'disabled':''}>Отправить ${ui.icon('arrow')}</button></div></form></section></div>`;const area=root.querySelector('#ai-query');area?.addEventListener('input',()=>{area.style.height='auto';area.style.height=Math.min(area.scrollHeight,260)+'px';});const list=root.querySelector('.ai-messages');if(list)list.scrollTop=list.scrollHeight;}
 root.innerHTML=`<div class="ai-wrap ai-chat-wrap"><div class="between"><span class="badge purple">${ui.icon('sparkles')}ИИ-помощник</span><a href="#/settings?tab=ai" class="text-link">${ui.icon('settings')}Настройки</a></div><div id="ai-chat-root"></div></div>${ui.footer()}`;render();
 async function busy(fn){if(working)return;working=true;failure='';render();try{await fn();}catch(error){failure=error.message||'Не удалось обратиться к ИИ.';}finally{working=false;render();}}
 const host=root.querySelector('#ai-chat-root');
 host.addEventListener('keydown',event=>{if(event.target.id==='ai-query'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229){event.preventDefault();if(!working)event.target.form?.requestSubmit();}});
 host.addEventListener('submit',event=>{if(event.target.id!=='ai-form')return;event.preventDefault();const question=root.querySelector('#ai-query').value.trim();if(!question)return;busy(async()=>{const id=selected()?.id||uid(),message={id:uid(),role:'user',content:question};await update(s=>{s.aiChats??=[];let c=s.aiChats.find(x=>x.id===id);if(!c){if(s.aiChats.length>=30)throw new Error('Достигнут предел в 30 диалогов. Удалите ненужный диалог.');c={id,title:question.slice(0,65),messages:[]};s.aiChats.unshift(c);}if(c.messages.length>=199)throw new Error('В диалоге достигнут предел сообщений. Начните новый.');if(!c.messages.length)c.title=question.slice(0,65);c.messages.push(message);s.activeAiChatId=id;});render();const history=chatById(id)?.messages||[],answer=await requestAI(history);await update(s=>{const c=(s.aiChats||[]).find(x=>x.id===id);if(c&&c.messages.some(m=>m.id===message.id))c.messages.push({id:uid(),role:'assistant',content:answer.text,sources:answer.sources,webStatus:answer.webStatus,webSources:answer.webSources});});});});
 host.addEventListener('click',event=>{const button=event.target.closest('[data-chat-action]');if(!button||button.disabled)return;const action=button.dataset.chatAction,chat=selected();
  if(action==='new'){busy(async()=>{const id=uid();await update(s=>{s.aiChats??=[];if(s.aiChats.length>=30)throw new Error('Достигнут предел в 30 диалогов. Удалите ненужный диалог.');s.aiChats.unshift({id,title:'Новый диалог',messages:[]});s.activeAiChatId=id;});});return;}
  if(action==='select'){busy(()=>update(s=>{s.activeAiChatId=button.dataset.chatId;}));return;}
  if(action==='retry'&&chat?.messages.at(-1)?.role==='user'){const id=chat.id,messageId=chat.messages.at(-1).id;busy(async()=>{const answer=await requestAI(chatById(id)?.messages||[]);await update(s=>{const c=(s.aiChats||[]).find(x=>x.id===id);if(c?.messages.at(-1)?.id===messageId)c.messages.push({id:uid(),role:'assistant',content:answer.text,sources:answer.sources,webStatus:answer.webStatus,webSources:answer.webSources});});});return;}
  if(['clear','delete','delete-message'].includes(action)&&chat){const names={clear:'Очистить все сообщения этого диалога?',delete:'Удалить этот диалог и все его сообщения?', 'delete-message':'Удалить это сообщение?'};const chatId=chat.id,messageId=button.dataset.messageId;ui.showModal('Подтвердите удаление',`<p>${names[action]} Это действие нельзя отменить.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Отмена</button><button class="btn btn-danger" id="ai-confirm-delete">Удалить</button></div>`);document.querySelector('#ai-confirm-delete').addEventListener('click',()=>{ui.closeModal();busy(()=>update(s=>{const c=(s.aiChats||[]).find(x=>x.id===chatId);if(!c)return;if(action==='delete'){s.aiChats=s.aiChats.filter(x=>x.id!==chatId);if(s.activeAiChatId===chatId)s.activeAiChatId=s.aiChats[0]?.id||null;}else if(action==='clear')c.messages=[];else c.messages=c.messages.filter(m=>m.id!==messageId);}));});return;}
  if(action==='article'&&chat){const messages=chat.messages.map(({role,content})=>({role,content}));ui.showModal('Подготовить статью по диалогу?',`<p>Весь диалог будет передан ИИ для подготовки черновика. Длинная история обрабатывается по частям и может потребовать нескольких платных запросов. Перед публикацией вы сможете проверить и исправить статью.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Отмена</button><button class="btn btn-primary" id="ai-confirm-article">Подготовить</button></div>`);document.querySelector('#ai-confirm-article').addEventListener('click',()=>{ui.closeModal();busy(async()=>{const {text}=await draftFromConversation(messages,requestAI,(current,total)=>{const loading=root.querySelector('.ai-loading');if(loading)loading.textContent=`Обрабатываем историю: ${current} из ${total}…`;});if(!root.isConnected)return;previewGeneratedArticle(text,ui,draft=>{const save=async()=>{await update(s=>{s.drafts??={};s.drafts.new=draft;});ui.closeModal();location.hash='#/editor';};if(state.drafts?.new){ui.showModal('Заменить текущий черновик?',`<p>У вас уже есть черновик новой статьи. Перенос заменит его; отмените действие, если хотите сначала сохранить его содержимое.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Отмена</button><button class="btn btn-danger" id="ai-replace-draft">Заменить черновик</button></div>`);document.querySelector('#ai-replace-draft').addEventListener('click',()=>save().catch(error=>ui.toast(error.message)));}else save().catch(error=>ui.toast(error.message));});});});}
 });
}
